    ADD COLUMN source text NOT NULL DEFAULT 'manual'
        CONSTRAINT chk_tasks_source CHECK (source IN ('manual', 'smart-schedule')),
    ADD COLUMN plan_id uuid;
CREATE INDEX idx_tasks_user_source_date ON tasks USING btree (user_id, source, date);

